function HasCloseElements(numbers: array of real; threshold: real): boolean;
begin
  var sorted := numbers.ToList;
  sorted.Sort;
  for var i := 0 to sorted.Count - 1 do
    for var j := i + 1 to sorted.Count - 1 do
      if Abs(sorted[i] - sorted[j]) <= threshold then
      begin
        Result := True;
        exit;
      end;
  Result := False;
end;


function SeparateParenGroups(parenString: string): array of string;
begin
  var stack := new Stack<string>;
  var current := '';
  var resultList := new List<string>;
  var ignoreSpace := False;

  for var i := 1 to parenString.Length do
  begin
    var ch := parenString[i];
    if ch = ' ' then
    begin
      ignoreSpace := True;
      continue;
    end;

    if ignoreSpace then
    begin
      ignoreSpace := False;
      current += ch;
      continue;
    end;

    if ch = '(' then
    begin
      if current.Length > 0 then
      begin
        stack.Push(current);
        current := '';
      end;
    end
    else if ch = ')' then
    begin
      if current.Length > 0 then
      begin
        current += ')';
        stack.Push(current);
        current := '';
      end
      else
      begin
        current += ')';
        resultList.Add(stack.Pop);
      end;
    end
    else
      current += ch;
  end;

  if current.Length > 0 then
    resultList.Add(current);

  Result := resultList.ToArray;
end;


