function MakePalindrome(str: string): string;
begin
  var n := str.Length;
  var L := new integer[n, n];
  var maxLen := 1;
  var start := 0;

  for var i := 0 to n - 1 do
    L[i, i] := 1;

  for var len := 2 to n do
  begin
    for var i := 0 to n - len do
    begin
      var j := i + len - 1;
      if str[i + 1] = str[j + 1] then
      begin
        L[i, j] := L[i + 1, j - 1] + 2;
        if L[i, j] > maxLen then
        begin
          maxLen := L[i, j];
          start := i;
        end;
      end;
    end;
  end;

  var res := '';
  if maxLen > 1 then
  begin
    for var i := start to start + maxLen - 1 do
      res += str[i + 1];
  end
  else
    res := str;

  Result := res + ReverseString(res);
end;


function StringXor(a, b: string): string;
begin
  var maxLen := Max(a.Length, b.Length);
  var res := '';
  for var i := 1 to maxLen do
  begin
    var aBit := if i <= a.Length then StrToInt(a[a.Length - i + 1]) else 0;
    var bBit := if i <= b.Length then StrToInt(b[b.Length - i + 1]) else 0;
    res := (aBit xor bBit) + res;
  end;
  Result := res;
end;


