function Fib4(n: integer): integer;
begin
  if n = 0 then
    Result := 0
  else if n = 1 then
    Result := 0
  else if n = 2 then
    Result := 2
  else if n = 3 then
    Result := 0
  else
  begin
    var fib4Values := new integer[n + 1];
    fib4Values[0] := 0;
    fib4Values[1] := 0;
    fib4Values[2] := 2;
    fib4Values[3] := 0;

    for var i := 4 to n do
      fib4Values[i] := fib4Values[i - 1] + fib4Values[i - 2] + fib4Values[i - 3] + fib4Values[i - 4];

    Result := fib4Values[n];
  end;
end;


