function Pluck(arr: array of integer): array of integer;
begin
  var smallestEven := integer.MaxValue;
  var smallestIndex := integer.MaxValue;
  var smallestValue := 0;
  var found := False;

  for var i := 0 to arr.Length - 1 do
  begin
    if (arr[i] mod 2 = 0) and (arr[i] <> smallestEven) then
    begin
      smallestEven := arr[i];
      found := True;
    end;

    if (arr[i] mod 2 = 0) and (arr[i] = smallestEven) then
    begin
      if i < smallestIndex then
      begin
        smallestIndex := i;
        smallestValue := arr[i];
      end;
    end;
  end;

  if found then
    Result := Arr(smallestValue, smallestIndex)
  else
    Result := new integer[0];
