function Minpath(grid: array of array of integer; k: integer): array of integer;

  function Dfs(x, y, k: integer; path: List<integer>): boolean;
  begin
    if (x = 0) and (y = 0) and (k = 0) then
    begin
      Result := True;
      exit;
    end;

    if (x < 0) or (y < 0) or (k = 0) then
    begin
      Result := False;
      exit;
    end;

    var visited := new HashSet<(integer, integer)>;
    path.Add(grid[x][y]);
    visited.Add((x, y));

    var directions := |(0, 1), (1, 0), (0, -1), (-1, 0)|;
    var ans := new List<integer>;

    foreach var (dx, dy) in directions do
    begin
      var nx := x + dx;
      var ny := y + dy;

      if (nx >= 0) and (nx < grid.Length) and (ny >= 0) and (ny < grid[0].Length) and
         (not visited.Contains((nx, ny))) and (grid[nx][ny] <> -1) then
      begin
        if Dfs(nx, ny, k - 1, path) then
        begin
          ans.Add(grid[nx][ny]);
          Result := True;
          exit;
        end;
      end;
    end;

    path.RemoveAt(path.Count - 1);
    Result := False;
  end;

begin
  var n := grid.Length;
  var path := new List<integer>;
  Dfs(n - 1, n - 1, k, path);
  Result := path.ToArray;
end;

begin
end.




