function FixSpaces(text: string): string;
begin
  var sb := new StringBuilder;
  var prevChar := #0;
  var hasSpace := False;
  var hasDash := False;
  var hasConsecutiveSpace := False;

  for var i := 1 to text.Length do
  begin
    var c := text[i];

    if c = ' ' then
    begin
      if not hasSpace then
        hasSpace := True;

      if hasDash and hasConsecutiveSpace then
        sb.Append('-')
      else
        sb.Append('_');

      hasDash := False;
      hasConsecutiveSpace := False;
    end
    else
    begin
      if hasSpace then
      begin
        if hasDash and hasConsecutiveSpace then
          sb.Append('-')
        else
          sb.Append(c);

        hasDash := False;
        hasConsecutiveSpace := False;
      end
      else
        sb.Append(c);

      if c = ' ' then
      begin
        hasDash := True;
        hasConsecutiveSpace := True;
      end
      else
      begin
        if prevChar = ' ' then
          hasDash := True
        else
          hasDash := False;

        hasConsecutiveSpace := False;
      end;

      prevChar := c;
    end;
  end;

  Result := sb.ToString;
end;


