  foreach var word in words do
    if IsPrime(word.Length) then
      primeWords.Add(word);

  Result := string.Join(' ', primeWords);
end;

begin
end.




function Simplify(x, n : string): boolean;
begin
  var xNum := StrToInt(x.Split('/')[0]);
  var xDenom := StrToInt(x.Split('/')[1]);
  var nNum := StrToInt(n.Split('/')[0]);
  var nDenom := StrToInt(n.Split('/')[1]);

  var gcd := gcd(xDenom, nDenom);
  var numerator := (xNum * nDenom) div gcd;
  var denominator := (xDenom * nNum) div gcd;

  Result := (numerator = denominator);
end;


function OrderByPoints(nums: array of integer): array of integer;
begin
  var sorted := nums.ToList;
  sorted.Sort((a, b) ->
  begin
    var sumA := a.ToString.Sum(c -> StrToInt(c.ToString));
    var sumB := b.ToString.Sum(c -> StrToInt(c.ToString));
    if sumA = sumB then
      Result := a.CompareTo(b)
    else
      Result := sumA.CompareTo(sumB);
  end);
  Result := sorted.ToArray;
end;

begin
end.




