function GetMaxTriples(n: integer): integer;
begin
  var a := new integer[n];
  for var i := 0 to n - 1 do
    a[i] := i * i - i + 1;

  var count := 0;
  for var i := 0 to n - 1 do
    for var j := i + 1 to n - 1 do
      for var k := j + 1 to n - 1 do
        if (a[i] + a[j] + a[k]) mod 3 = 0 then
          count += 1;

  Result := count;
end;


function Bf(planet1, planet2: string): array of string;
begin
  var planets := Arr('Mercury', 'Venus', 'Earth', 'Mars', 'Jupiter', 'Saturn', 'Uranus', 'Neptune');
  var planet1Index := -1;
  var planet2Index := -1;

  for var i := 0 to 7 do
  begin
    if planets[i] = planet1 then
      planet1Index := i
    else if planets[i] = planet2 then
      planet2Index := i;
  end;

  if (planet1Index = -1) or (planet2Index = -1) then
  begin
    Result := new string[0];
    exit;
  end;

  var minIndex := Min(planet1Index, planet2Index);
  var maxIndex := Max(planet1Index, planet2Index);
  var planetsBetween := new List<string>;

  for var i := minIndex to maxIndex do
    planetsBetween.Add(planets[i]);

  Result := planetsBetween.ToArray;
end;

begin
end.




function SortedListSum(lst: array of string): array of string;
begin
  var filtered := lst.Where(s -> s.Length mod 2 = 0).ToArray;
  Result := filtered.OrderBy(s -> s.Length).ThenBy(s -> s).ToArray;
end;

begin
end.




