function DoubleTheDifference(lst : array of real): integer;
begin
  var sum := 0;
  foreach var num in lst do
    if num mod 2 <> 0 then
      sum += num * num;
  Result := sum;
end;


function Compare(game, guess: array of integer): array of integer;
begin
  var res := new List<integer>;
  for var i := 0 to game.Length - 1 do
  begin
    if game[i] = guess[i] then
      res.Add(0)
    else
      res.Add(Abs(guess[i] - game[i]));
  end;
  Result := res.ToArray;
end;

begin
end.




function StrongestExtension(className: string; extensions: array of string): string;
begin
  var maxStrength := -1000000000000;
  var strongestExtension := '';

  foreach var extension in extensions do
  begin
    var cap := 0;
    var sm := 0;
    foreach var ch in extension do
    begin
      if Char.IsUpper(ch) then
        cap += 1;
      if Char.IsLower(ch) then
        sm += 1;
    end;
    var strength := cap - sm;
    if strength > maxStrength then
    begin
      maxStrength := strength;
      strongestExtension := extension;
    end;
  end;

  Result := className + '.' + strongestExtension;
end;

begin
end.




function CycpatternCheck(a, b: string): boolean;
begin
  var n := a.Length;
  for var i := 0 to n - 1 do
  begin
    var temp := a.Substring(i, n);
    if (temp.Contains(b)) or (temp.Substring(1, n - 1).Contains(b)) then
    begin
      Result := True;
      exit;
    end;
  end;
  Result := False;
end;

begin
end.




function EvenOddCount(num: integer): (integer, integer);
begin
  var evenCount := 0;
  var oddCount := 0;
  var absNum := Abs(num);

  while absNum > 0 do
  begin
    var digit := absNum mod 10;
    if digit mod 2 = 0 then
      evenCount += 1
    else
      oddCount += 1;
    absNum := absNum div 10;
  end;

  Result := (evenCount, oddCount);
end;


function IntToMiniRoman(number: integer): string;
begin
  var values := |1000, 900, 500, 400, 100, 90, 50, 40, 10, 9, 5, 4|;
  var symbols := |'m', 'cm', 'd', 'cd', 'c', 'xc', 'l', 'xl', 'x', 'ix', 'v', 'iv', 'i'|;

  var roman := '';
  var i := 0;

  while number > 0 do
  begin
    for var j := 1 to number div values[i] do
    begin
      roman += symbols[i];
      number -= values[i];
    end;
    i += 1;
  end;

  Result := roman;
end;


function RightAngleTriangle(a, b, c: integer): boolean;
begin
  var sides := new List<integer>;
  sides.Add(a);
  sides.Add(b);
  sides.Add(c);
  sides.Sort;
  Result := (sides[0] * sides[0]) + (sides[1] * sides[1]) = (sides[2] * sides[2]);
end;


function FindMax(words: array of string): string;
begin
  var maxUnique := 0;
  var maxWord := '';
  foreach var word in words do
  begin
    var uniqueChars := new HashSet<char>(word.ToCharArray);
    var uniqueCount := uniqueChars.Count;
    if uniqueCount > maxUnique then
    begin
      maxUnique := uniqueCount;
      maxWord := word;
    end;
  end;
  Result := maxWord;
end;


function Eat(number, need, remaining: integer): (integer, integer);
begin
  var eaten := number;
  var left := remaining;

  if left >= need then
  begin
    eaten += need;
    left -= need;
  end
  else
  begin
    eaten += left;
    left := 0;
  end;

  Result := (eaten, left);
end;


function DoAlgebra(op: array of string; operand: array of integer): integer;
begin
  var res := operand[0];
  for var i := 0 to op.Length - 1 do
  begin
    var opStr := op[i];
    var num := operand[i + 1];
    if opStr = '+' then
      res += num
    else if opStr = '-' then
      res -= num
    else if opStr = '*' then
      res *= num
    else if opStr = '//' then
      res := Trunc(res / num)
    else if opStr = '**' then
      res := Trunc(Power(res, num));
  end;
  Result := res;
end;


function Solve(s: string): string;
begin
  var sb := new StringBuilder;
  foreach var ch in s do
  begin
    if Char.IsLetter(ch) then
    begin
      if Char.IsLower(ch) then
        sb.Append(Char.ToUpper(ch))
      else
        sb.Append(Char.ToLower(ch));
    end
    else
      sb.Append(ch);
  end;
  Result := sb.ToString;
end;

begin
end.




function StringToMd5(text: string): string;
begin
  if string.IsNullOrEmpty(text) then
  begin
    Result := nil;
    exit;
  end;

  var md5 := System.Security.Cryptography.MD5.Create;
  var bytes := Encoding.UTF8.GetBytes(text);
  var hash := md5.ComputeHash(bytes);
  Result := BitConverter.ToString(hash).Replace('-', '');
end;


function GenerateIntegers(a, b: integer): array of integer;
begin
  var res := new List<integer>;
  for var i := a to b step 2 do
    if i mod 2 = 0 then
      res.Add(i);
  Result := res.ToArray;
end;
